<script>(()=>{const f=document.getElementById('member-transfer-form'),recipient=document.getElementById('transfer-recipient-result'),status=document.getElementById('transfer-otp-status');const call=async(url,data)=>{const r=await fetch(url,{method:data?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':f.querySelector('[name=_token]').value},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to verify.');return d;};let verified='';document.getElementById('verify-transfer-recipient').onclick=async()=>{try{const d=await call({{ Illuminate\Support\Js::from(route('member.transfer.recipient')) }}+'?recipient='+encodeURIComponent(f.recipient.value));verified=f.recipient.value;recipient.textContent='User verified: '+d.username+' — '+d.name;recipient.style.color='#86efac';}catch(e){verified='';recipient.textContent=e.message;recipient.style.color='#fda4af';}};document.getElementById('send-transfer-otp').onclick=async e=>{const b=e.target;b.disabled=true;try{if(verified!==f.recipient.value)throw Error('Verify the recipient User ID first.');const d=await call({{ Illuminate\Support\Js::from(route('member.transfer-otp.send')) }},{recipient:f.recipient.value,amount:f.amount.value,request_key:f.request_key.value});f.otp_challenge_id.value=d.challenge_id;status.textContent=d.message;status.style.color='#86efac';}catch(e){status.textContent=e.message;status.style.color='#fda4af';}finally{b.disabled=false;}};f.amount.oninput=()=>{f.otp_challenge_id.value='';f.email_otp.value='';status.textContent='Amount changed — send a new OTP.';};f.recipient.oninput=()=>{verified='';recipient.textContent='Recipient changed — verify this ID again.';f.otp_challenge_id.value='';};})();</script>
